import type { MenuItem } from "@jcoder-stack/abp-react/react";
import { type ComponentProps, memo, type ReactNode } from "react";
import { BrandMark } from "@/components/abp/layout/brand-mark";
import { NavMain } from "@/components/abp/layout/nav-main";
import { NavSearch } from "@/components/abp/layout/nav-search";
import { NavUser } from "@/components/abp/layout/nav-user";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from "@/components/ui/sidebar";

/** memo：布局壳每次导航都重渲染，侧栏 props 引用稳定时整棵子树跳过重执行。激活态高亮由 NavMain 内部订阅 pathname 自行更新，不依赖父级渲染。 */
export const AppSidebar = memo(function AppSidebar({
  items,
  title,
  logo,
  userMenuItems,
  ...props
}: {
  items: MenuItem[];
  title: string;
  logo?: ReactNode;
  userMenuItems?: ReactNode;
} & ComponentProps<typeof Sidebar>) {
  return (
    <Sidebar variant="inset" collapsible="icon" {...props}>
      <SidebarHeader>
        <SidebarMenu>
          <SidebarMenuItem>
            <SidebarMenuButton size="lg" asChild>
              <a href="/">
                {/* size-8! 提权：SidebarMenuButton 带 [&>svg]:size-4，会把标识压成 16px */}
                {logo ?? <BrandMark className="size-8! shrink-0" />}
                <span className="truncate font-medium">{title}</span>
              </a>
            </SidebarMenuButton>
          </SidebarMenuItem>
        </SidebarMenu>
        <NavSearch items={items} />
      </SidebarHeader>
      <SidebarContent>
        <NavMain items={items} />
      </SidebarContent>
      <SidebarFooter>
        <NavUser userMenuItems={userMenuItems} />
      </SidebarFooter>
    </Sidebar>
  );
});

import { cn } from "@/lib/utils";

/**
 * 产品标识。换成自己的品牌时改这一个文件即可，侧栏、落地页顶导航、登录页都取它。
 *
 * 颜色走 `--brand-*` token 而非写死：暗色下轮廓翻白、播放三角换成青色（深蓝底上的
 * 蓝三角对比度不够），这两处切换由 token 自己完成，组件不需要知道当前是什么主题。
 * 尺寸由外部的 className 给（`size-*`），viewBox 保证任意尺寸都不失真。
 */
export function BrandMark({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 64 64"
      fill="none"
      className={cn("size-8", className)}
      role="img"
      aria-label="ABP React Start"
    >
      <path
        d="M32 4.5 L54.5 17.5 V43.5 L32 56.5 L9.5 43.5 V17.5 Z"
        className="stroke-brand-ink"
        strokeWidth={5}
        strokeLinejoin="round"
      />
      <path
        d="M27 23 L43 32 L27 41 Z"
        className="fill-brand-mark stroke-brand-mark"
        strokeWidth={3.5}
        strokeLinejoin="round"
      />
      <circle
        cx={54.5}
        cy={17.5}
        r={5.5}
        className="fill-brand-spark stroke-brand-ink-contrast"
        strokeWidth={2.5}
      />
    </svg>
  );
}

import { type MenuItem, useLocalization, useMenu } from "@jcoder-stack/abp-react/react";
import { Link, useRouterState } from "@tanstack/react-router";
import { ChevronRight } from "lucide-react";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import {
  SidebarGroup,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
} from "@/components/ui/sidebar";

/** 权限剪枝后的主菜单。 */
export function NavMain({ items }: { items: MenuItem[] }) {
  const menu = useMenu(items);
  const L = useLocalization();
  const pathname = useRouterState({ select: (s) => s.location.pathname });
  return (
    <SidebarGroup>
      <SidebarMenu>
        {menu.map((item) =>
          item.children !== undefined && item.children.length > 0 ? (
            <Collapsible
              key={item.key}
              asChild
              defaultOpen={item.children.some((child) => child.to === pathname)}
              className="group/collapsible"
            >
              <SidebarMenuItem>
                <CollapsibleTrigger asChild>
                  <SidebarMenuButton tooltip={L(item.label)}>
                    {item.icon}
                    <span>{L(item.label)}</span>
                    <ChevronRight className="ml-auto transition-transform duration-200 group-data-[state=open]/collapsible:rotate-90" />
                  </SidebarMenuButton>
                </CollapsibleTrigger>
                <CollapsibleContent>
                  <SidebarMenuSub>
                    {item.children.map((child) => (
                      <SidebarMenuSubItem key={child.key}>
                        <SidebarMenuSubButton asChild isActive={child.to === pathname}>
                          <Link to={child.to ?? "/"}>
                            {child.icon}
                            <span>{L(child.label)}</span>
                          </Link>
                        </SidebarMenuSubButton>
                      </SidebarMenuSubItem>
                    ))}
                  </SidebarMenuSub>
                </CollapsibleContent>
              </SidebarMenuItem>
            </Collapsible>
          ) : (
            <SidebarMenuItem key={item.key}>
              <SidebarMenuButton asChild isActive={item.to === pathname} tooltip={L(item.label)}>
                <Link to={item.to ?? "/"}>
                  {item.icon}
                  <span>{L(item.label)}</span>
                </Link>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ),
        )}
      </SidebarMenu>
    </SidebarGroup>
  );
}

import { type MenuItem, useLocalization, useMenu } from "@jcoder-stack/abp-react/react";
import { useNavigate } from "@tanstack/react-router";
import { Search } from "lucide-react";
import { useEffect, useState } from "react";
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

interface SearchEntry {
  key: string;
  label: string;
  to: string;
  icon?: MenuItem["icon"];
  group?: string;
}

// 上游 items 已按权限剪枝
function flattenMenu(menu: MenuItem[], L: (key: string) => string): SearchEntry[] {
  const entries: SearchEntry[] = [];
  for (const item of menu) {
    if (item.children !== undefined && item.children.length > 0) {
      const group = L(item.label);
      for (const child of item.children) {
        if (child.to !== undefined) {
          entries.push({
            key: child.key,
            label: L(child.label),
            to: child.to,
            icon: child.icon,
            group,
          });
        }
      }
    } else if (item.to !== undefined) {
      entries.push({ key: item.key, label: L(item.label), to: item.to, icon: item.icon });
    }
  }
  return entries;
}

/** 侧栏菜单搜索：⌘K/Ctrl+K 或点击触发 Command 弹层，模糊过滤权限内菜单，选中即导航。 */
export function NavSearch({ items }: { items: MenuItem[] }) {
  const L = useLocalization();
  const menu = useMenu(items);
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);
  // SSR 拿不到平台信息，挂载后再按真实平台切 ⌘/Ctrl 角标，避免水合不一致。
  const [isMac, setIsMac] = useState(false);

  useEffect(() => {
    setIsMac(/Mac|iPhone|iPad/i.test(`${navigator.platform} ${navigator.userAgent}`));
  }, []);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "k" && (event.metaKey || event.ctrlKey)) {
        event.preventDefault();
        setOpen((prev) => !prev);
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, []);

  const entries = flattenMenu(menu, L);
  const groups = new Map<string, SearchEntry[]>();
  for (const entry of entries) {
    const bucket = entry.group ?? "";
    groups.set(bucket, [...(groups.get(bucket) ?? []), entry]);
  }

  const select = (entry: SearchEntry) => {
    setOpen(false);
    void navigate({ to: entry.to });
  };

  return (
    <>
      <SidebarMenu>
        <SidebarMenuItem>
          <SidebarMenuButton tooltip={L("Layout:Search")} onClick={() => setOpen(true)}>
            <Search />
            <span>{L("Layout:Search")}</span>
            <kbd className="ml-auto text-xs text-muted-foreground group-data-[collapsible=icon]:hidden">
              {isMac ? "⌘K" : "Ctrl+K"}
            </kbd>
          </SidebarMenuButton>
        </SidebarMenuItem>
      </SidebarMenu>
      <CommandDialog
        open={open}
        onOpenChange={setOpen}
        title={L("Layout:Search")}
        description={L("Layout:SearchPlaceholder")}
      >
        <CommandInput placeholder={L("Layout:SearchPlaceholder")} />
        <CommandList>
          <CommandEmpty>{L("Layout:SearchEmpty")}</CommandEmpty>
          {[...groups.entries()].map(([group, groupEntries]) => (
            <CommandGroup
              key={group === "" ? "__top" : group}
              heading={group === "" ? undefined : group}
            >
              {groupEntries.map((entry) => (
                <CommandItem
                  key={entry.key}
                  value={`${entry.group ?? ""} ${entry.label}`.trim()}
                  onSelect={() => select(entry)}
                >
                  {entry.icon}
                  {entry.label}
                </CommandItem>
              ))}
            </CommandGroup>
          ))}
        </CommandList>
      </CommandDialog>
    </>
  );
}

import { useLocalization, useSession } from "@jcoder-stack/abp-react/react";
import { Link } from "@tanstack/react-router";
import { ChevronsUpDown, LogIn, LogOut } from "lucide-react";
import type { ReactNode } from "react";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@/components/ui/sidebar";

export function NavUser({ userMenuItems }: { userMenuItems?: ReactNode } = {}) {
  const { identity, status } = useSession();
  const L = useLocalization();
  const { isMobile } = useSidebar();

  if (status !== "authenticated" || identity.user === null) {
    return (
      <SidebarMenu>
        <SidebarMenuItem>
          <SidebarMenuButton asChild size="lg">
            <Link to="/login" search={{ error: undefined }}>
              <LogIn />
              <span>{L("Layout:Login")}</span>
            </Link>
          </SidebarMenuButton>
        </SidebarMenuItem>
      </SidebarMenu>
    );
  }

  const user = identity.user;
  const initials = user.userName.slice(0, 2).toUpperCase();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <SidebarMenuButton
              size="lg"
              className="data-[state=open]:bg-sidebar-accent data-[state=open]:text-sidebar-accent-foreground"
            >
              <Avatar className="h-8 w-8 rounded-lg">
                <AvatarFallback className="rounded-lg">{initials}</AvatarFallback>
              </Avatar>
              <div className="grid flex-1 text-left text-sm leading-tight">
                <span className="truncate font-medium">{user.userName}</span>
                {user.email !== undefined && (
                  <span className="truncate text-xs text-muted-foreground">{user.email}</span>
                )}
              </div>
              <ChevronsUpDown className="ml-auto size-4" />
            </SidebarMenuButton>
          </DropdownMenuTrigger>
          <DropdownMenuContent
            className="w-(--radix-dropdown-menu-trigger-width) min-w-56 rounded-lg"
            side={isMobile ? "bottom" : "right"}
            align="end"
            sideOffset={4}
          >
            <DropdownMenuLabel className="truncate font-normal">{user.userName}</DropdownMenuLabel>
            <DropdownMenuSeparator />
            {userMenuItems}
            <DropdownMenuItem asChild>
              <a href="/api/auth/logout">
                <LogOut />
                {L("Layout:Logout")}
              </a>
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

import type { MenuItem } from "@jcoder-stack/abp-react/react";
import { AbpBreadcrumb } from "@/components/abp/layout/abp-breadcrumb";
import { LocaleSwitcher } from "@/components/abp/layout/locale-switcher";
import { TenantSwitcher } from "@/components/abp/layout/tenant-switcher";
import { ThemeToggle } from "@/components/abp/layout/theme-toggle";
import { Separator } from "@/components/ui/separator";
import { SidebarTrigger } from "@/components/ui/sidebar";

export function SiteHeader({ items }: { items: MenuItem[] }) {
  return (
    <header className="sticky top-0 z-10 flex h-14 shrink-0 items-center gap-2 border-b bg-background px-4 md:rounded-t-xl">
      <SidebarTrigger className="-ml-1" />
      <Separator orientation="vertical" className="mr-2 data-[orientation=vertical]:h-4" />
      <AbpBreadcrumb items={items} />
      <div className="ml-auto flex items-center gap-1">
        <LocaleSwitcher />
        <TenantSwitcher />
        <ThemeToggle />
      </div>
    </header>
  );
}

import { type MenuItem, useBreadcrumbs, useLocalization } from "@jcoder-stack/abp-react/react";
import { Link, useRouterState } from "@tanstack/react-router";
import { Fragment } from "react";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";

/** 面包屑：菜单树 × 当前路径 → 祖先链；末项为当前页。 */
export function AbpBreadcrumb({ items }: { items: MenuItem[] }) {
  const pathname = useRouterState({ select: (s) => s.location.pathname });
  const chain = useBreadcrumbs(items, pathname);
  const L = useLocalization();
  if (chain.length === 0) return null;
  return (
    <Breadcrumb>
      <BreadcrumbList>
        {chain.map((item, index) => (
          <Fragment key={item.key}>
            {index > 0 && <BreadcrumbSeparator className="hidden md:block" />}
            <BreadcrumbItem className={index < chain.length - 1 ? "hidden md:block" : undefined}>
              {index === chain.length - 1 ? (
                <BreadcrumbPage>{L(item.label)}</BreadcrumbPage>
              ) : item.to !== undefined ? (
                <BreadcrumbLink asChild>
                  <Link to={item.to}>{L(item.label)}</Link>
                </BreadcrumbLink>
              ) : (
                <span>{L(item.label)}</span>
              )}
            </BreadcrumbItem>
          </Fragment>
        ))}
      </BreadcrumbList>
    </Breadcrumb>
  );
}

import { useAppConfig, useCulture, useLocalization } from "@jcoder-stack/abp-react/react";
import { useRouterState } from "@tanstack/react-router";
import { Check, Languages } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";

/** 语言切换：列表来自 app-config 的真实语言集；经 /api/culture 302 生效（cookie 优先机制）。 */
export function LocaleSwitcher() {
  const { localization } = useAppConfig();
  const current = useCulture();
  const L = useLocalization();
  const pathname = useRouterState({ select: (s) => s.location.pathname });
  if (localization.languages.length === 0) return null;
  return (
    <DropdownMenu>
      <Tooltip>
        <TooltipTrigger asChild>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className="size-8 text-muted-foreground hover:text-foreground"
              aria-label={L("Layout:Language")}
            >
              <Languages />
            </Button>
          </DropdownMenuTrigger>
        </TooltipTrigger>
        <TooltipContent>{L("Layout:Language")}</TooltipContent>
      </Tooltip>
      <DropdownMenuContent align="end">
        {localization.languages.map((lang) => (
          <DropdownMenuItem key={lang.cultureName} asChild>
            <a
              href={`/api/culture?culture=${encodeURIComponent(lang.cultureName)}&returnUrl=${encodeURIComponent(pathname)}`}
            >
              <span className="flex-1">{lang.displayName}</span>
              {lang.cultureName === current && <Check className="size-4" />}
            </a>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { useAppConfig, useLocalization, useSession } from "@jcoder-stack/abp-react/react";
import { useRouterState } from "@tanstack/react-router";
import { Building2 } from "lucide-react";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

/** ABP 惯例租户切换框：输入租户名经 /api/tenant 302 落 cookie；留空切回宿主；多租户不可用时不渲染。 */
export function TenantSwitcher() {
  const { currentTenant } = useAppConfig();
  const { identity } = useSession();
  const L = useLocalization();
  const pathname = useRouterState({ select: (s) => s.location.pathname });
  const [name, setName] = useState(identity.tenant?.name ?? "");
  if (!currentTenant.isAvailable) return null;

  const currentLabel = identity.tenant?.name ?? L("Layout:Host");
  const confirm = () => {
    const tenant = name.trim();
    const query =
      tenant === ""
        ? `returnUrl=${encodeURIComponent(pathname)}`
        : `tenant=${encodeURIComponent(tenant)}&returnUrl=${encodeURIComponent(pathname)}`;
    window.location.assign(`/api/tenant?${query}`);
  };

  // 触发器无 aria-label：可见文本（当前租户/宿主）就是可及名，覆盖它会破坏测试与读屏
  return (
    <Dialog>
      <DialogTrigger asChild>
        <Button variant="ghost" size="sm" className="text-muted-foreground hover:text-foreground">
          <Building2 />
          <span className="hidden md:inline">{currentLabel}</span>
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-sm">
        <DialogHeader>
          <DialogTitle>{L("Layout:SwitchTenant")}</DialogTitle>
          <DialogDescription>{L("Layout:TenantSwitchHint")}</DialogDescription>
        </DialogHeader>
        <div className="grid gap-2">
          <Label htmlFor="tenant-name">{L("Layout:TenantName")}</Label>
          <Input
            id="tenant-name"
            value={name}
            onChange={(event) => setName(event.target.value)}
            onKeyDown={(event) => event.key === "Enter" && confirm()}
          />
        </div>
        <DialogFooter>
          <DialogClose asChild>
            <Button variant="outline">{L("Layout:Cancel")}</Button>
          </DialogClose>
          <Button onClick={confirm}>{L("Layout:Confirm")}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import { Check, Moon, Sun } from "lucide-react";
import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";

type Theme = "light" | "dark" | "system";

const THEMES: { value: Theme; labelKey: string }[] = [
  { value: "light", labelKey: "Layout:ThemeLight" },
  { value: "dark", labelKey: "Layout:ThemeDark" },
  { value: "system", labelKey: "Layout:ThemeSystem" },
];

function applyTheme(theme: Theme) {
  localStorage.setItem("theme", theme);
  const dark =
    theme === "dark" ||
    (theme === "system" && window.matchMedia("(prefers-color-scheme: dark)").matches);
  document.documentElement.classList.toggle("dark", dark);
}

/** 主题三选（light/dark/system），当前项带对勾；与 __root 的首绘内联脚本共用 localStorage.theme 约定。 */
export function ThemeToggle() {
  const L = useLocalization();
  // SSR 读不到 localStorage，挂载后再同步已存偏好。
  const [theme, setTheme] = useState<Theme>("system");
  useEffect(() => {
    const stored = localStorage.getItem("theme");
    if (stored === "light" || stored === "dark" || stored === "system") setTheme(stored);
  }, []);

  const pick = (value: Theme) => {
    setTheme(value);
    applyTheme(value);
  };

  return (
    <DropdownMenu>
      <Tooltip>
        <TooltipTrigger asChild>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className="size-8 text-muted-foreground hover:text-foreground"
              aria-label={L("Layout:Theme")}
            >
              <Sun className="scale-100 rotate-0 transition-all dark:scale-0 dark:-rotate-90" />
              <Moon className="absolute scale-0 rotate-90 transition-all dark:scale-100 dark:rotate-0" />
            </Button>
          </DropdownMenuTrigger>
        </TooltipTrigger>
        <TooltipContent>{L("Layout:Theme")}</TooltipContent>
      </Tooltip>
      <DropdownMenuContent align="end">
        {THEMES.map((item) => (
          <DropdownMenuItem key={item.value} onClick={() => pick(item.value)}>
            {L(item.labelKey)}
            {theme === item.value && <Check className="ml-auto size-4" />}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
